// ─── Insert Veg Items ─────────────────────────────────────
const vegDocs = vegItems.map(item => ({
  name: item.name,
  description: item.desc,
  price: item.price,
  image: pick(vegImages),
  category: item.cat,
  isAvailable: true,
  restaurant: pick(allRestaurantIds),
  isVeg: true,
  rating: parseFloat((Math.random() * 1.5 + 3.5).toFixed(1)),
  ratingCount: randInt(50, 2000),
  createdAt: now(),
  updatedAt: now(),
}));

console.log('🥗 Inserting veg items...');
const vegResult = await db.collection('fooditems').insertMany(vegDocs);
console.log(`   ✅ Inserted ${Object.keys(vegResult.insertedIds).length} veg items.\n`);

// ─── Insert Non-Veg Items ─────────────────────────────────
const nonVegDocs = nonVegItems.map(item => ({
  name: item.name,
  description: item.desc,
  price: item.price,
  image: pick(nonVegImages),
  category: item.cat,
  isAvailable: true,
  restaurant: pick(allRestaurantIds),
  isVeg: false,
  rating: parseFloat((Math.random() * 1.5 + 3.5).toFixed(1)),
  ratingCount: randInt(50, 3000),
  createdAt: now(),
  updatedAt: now(),
}));

console.log('🍗 Inserting non-veg items...');
const nonVegResult = await db.collection('fooditems').insertMany(nonVegDocs);
console.log(`   ✅ Inserted ${Object.keys(nonVegResult.insertedIds).length} non-veg items.\n`);

// ─── Final Count ──────────────────────────────────────────
const total = await db.collection('fooditems').countDocuments();
const totalVeg = await db.collection('fooditems').countDocuments({ isVeg: true });
const totalNonVeg = await db.collection('fooditems').countDocuments({ isVeg: false });

